+            ) {
+              clearTimeout(timer);
+              record({ kind: 'response', ...identity, id, value });
+              resolve(value);
+            },
+            /** 실제 입력·관측을 연결하고 실패를 호출자에게 전달한다. */ reject(
+              error,
+            ) {
+              clearTimeout(timer);
+              reject(error);
+            },
+          });
+          child.stdin.write(
+            JSON.stringify({ jsonrpc: '2.0', id, method, params }) + '\n',
